function animateOther(old,newGame,previous,skip=new Set()){if(reduced)return;const used=new Set();for(const item of old){if(skip.has(item.id)||used.has(item.id))continue;used.add(item.id);const target=document.querySelector(`[data-move="${item.id}"]`);if(target){const r=target.getBoundingClientRect(),dx=item.rect.x-r.x,dy=item.rect.y-r.y;if(Math.abs(dx)+Math.abs(dy)>3)target.animate([{transform:`translate(${dx}px,${dy}px) rotate(-3deg)`},{transform:'translate(0,0) rotate(0deg)'}],{duration:400,easing:'cubic-bezier(.2,.8,.2,1)'});}else{let p=newGame.piles.findIndex(h=>h.some(c=>c.id===item.id));if(p<0)continue;const dest=document.querySelector(`[data-pile-target="${p}"]`)?.getBoundingClientRect();if(!dest)continue;const temp=document.createElement('div');temp.innerHTML=item.html;const el=temp.firstElementChild;el.classList.add('flying');Object.assign(el.style,{left:item.rect.x+'px',top:item.rect.y+'px',width:item.rect.width+'px',height:item.rect.height+'px'});$('flightLayer').append(el);const anim=el.animate([{transform:'translate(0,0) rotate(0)',opacity:1},{transform:`translate(${dest.x-item.rect.x}px,${dest.y-item.rect.y}px) scale(.4) rotate(5deg)`,opacity:.2}],{duration:470,easing:'cubic-bezier(.3,.1,.2,1)'});anim.onfinish=()=>el.remove();}}}
