function enterRoom(r){receiveClock(r);cancelMovePlayback();enterTable();cancelDealAnimation();online={code:r.code,token:r.token,seat:r.seat,rated:!!r.rated,tournament:r.tournament||null};seat=r.seat;save('khasino-room',online);save('khasino-active','online');clearTimeout(botTimer);clearInterval(pollTimer);$('modal').close();g=r.game;draft=[];clearSelection();render(true);pollTimer=setInterval(()=>{if(!document.hidden&&!busy)poll();},500);toast('You’re at table '+online.code+'.');}
let polling=false;async function poll(){if(!online||polling)return;polling=true;try{const r=await api('/api/rooms/'+online.code,{token:online.token});receiveClock(r);if(g.version!==r.game.version||g.status!==r.game.status||JSON.stringify(g.names)!==JSON.stringify(r.game.names)||JSON.stringify(g.leaveOffer)!==JSON.stringify(r.game.leaveOffer))setGame(r.game);$('connection').classList.remove('footer-error');}catch(e){$('connection').textContent='Connection paused · reconnecting';$('connection').classList.add('footer-error');}finally{polling=false;}}
function renderLobby(){const waiting=online&&g.status==='lobby';$('lobby').hidden=!waiting;if(!waiting)return;const joined=g.names.filter(n=>n!=='Open seat').length;$('lobby').innerHTML=`<span class="eyebrow" style="color:#acc3a0">YOUR PRIVATE TABLE</span><h3>The best games start with friends.</h3><p>Send your people the code.<br>We’ll deal when all ${g.players} seats are filled.</p><div class="room-code">${online.code}</div><button id="copyLobby" class="outline-button">Copy invitation link</button><small>${joined} of ${g.players} players seated</small>`;$('copyLobby').onclick=copyInvite;}
