function offlineMove(p,actions){let next=E.beginLeaveOffer(g,p,actions);const o=next.leaveOffer;if(o&&o.partner!==seat){const can=next.hands[o.partner].some(c=>c.rank===o.value)&&next.table.filter(t=>t.kind==='build'&&t.owner===o.partner).length<2&&next.table.filter(t=>t.kind==='build'&&t.owner===o.actor).length<2;next=E.answerLeaveOffer(next,o.partner,o.id,can);}return next;}
function renderLeaveOffer(){const o=g?.leaveOffer,remaining=o?Math.max(0,Math.ceil((o.endsAt-Date.now()-(online?serverOffset:0))/1000)):0;
 let prompt=$('leavePrompt');if(!prompt){prompt=document.createElement('div');prompt.id='leavePrompt';prompt.className='leave-prompt';prompt.setAttribute('role','dialog');prompt.setAttribute('aria-label','Leave it?');prompt.innerHTML='<div><h3>Leave it?</h3><p id="leaveCountdown"></p><div class="leave-buttons"><button id="leaveYes">Yes</button><button id="leaveNo">No</button></div></div>';document.body.append(prompt);$('leaveYes').onclick=()=>replyLeave(true);$('leaveNo').onclick=()=>replyLeave(false);}
 prompt.hidden=atHome||!o||o.partner!==seat||o.answer!==null||remaining===0;
 if(!o)return;
 $('turnBadge').textContent='Leave it? · '+remaining+'s';$('leaveCountdown').textContent=o.value+' build · '+remaining+'s';
 $('leaveYes').disabled=busy;$('leaveNo').disabled=busy;
}
