setInterval(()=>{if(!g?.leaveOffer)return;if(!online&&Date.now()>=g.leaveOffer.endsAt){try{setGame(E.resolveLeaveOffer(g));}catch(e){toast(e.message);}return;}renderLeaveOffer();},200);

