async function accountDialog(create=false){
 try{playerAccount=await api('/api/profile');renderAccount();}catch(e){showModal(`<h3 class="modal-title">Account unavailable</h3><p class="modal-copy">${esc(e.message)}</p><button id="accountRetry" class="primary-button">Try again</button>`);$('accountRetry').onclick=()=>accountDialog(create);return;}
 if(!playerAccount.signedIn){const returnTo='/?account='+ (create?'create':'login');showModal(`<p class="modal-eyebrow">KHASINO ACCOUNT</p><h3 class="modal-title">${create?'Create your account.':'Welcome back.'}</h3><p class="modal-copy">Continue with ChatGPT, then choose your Khasino display name.</p><a class="account-continue" href="/signin-with-chatgpt?return_to=${encodeURIComponent(returnTo)}" target="_top">Continue with ChatGPT</a><p class="modal-copy">You can still play the computer as a guest.</p>`);return;}
 const profile=playerAccount.profile;
 showModal(`<p class="modal-eyebrow">${profile?'YOUR PROFILE':'KHASINO ACCOUNT'}</p><h3 class="modal-title">${profile?'Your seat at the table.':'Choose your table name.'}</h3><p class="modal-copy">${profile?'Your profile is saved online.':'This is the name other players will see.'}</p><form id="profileForm"><label class="field">Display name<input id="profileName" required minlength="1" maxlength="20" autocomplete="nickname" value="${esc(profile?.displayName||load('khasino-nickname',''))}" placeholder="Your name"></label><p id="profileError" class="profile-error" role="alert"></p><button id="saveProfile" class="primary-button" type="submit">${profile?'Save changes':'Create account'}</button></form><a class="account-signout" href="/signout-with-chatgpt?return_to=%2F" target="_top">Log out</a>`);
 $('profileForm').onsubmit=async e=>{e.preventDefault();$('saveProfile').disabled=true;$('profileError').textContent='';try{playerAccount=await api('/api/profile',{displayName:$('profileName').value});save('khasino-nickname',playerAccount.profile.displayName);renderAccount();$('modal').close();toast(profile?'Profile updated.':'Your Khasino account is ready.');}catch(error){$('profileError').textContent=error.message;$('saveProfile').disabled=false;}};
}
$('homeLogin').onclick=()=>accountDialog(false);$('homeSignup').onclick=()=>accountDialog(true);$('homeProfile').onclick=()=>accountDialog();profileMenuButton.onclick=()=>{ $('tableMenu').open=false;accountDialog();};
api('/api/profile').then(data=>{playerAccount=data;renderAccount();if(new URL(location.href).searchParams.has('account')){const next=new URL(location.href);const create=next.searchParams.get('account')==='create';next.searchParams.delete('account');history.replaceState(null,'',next.pathname+next.search+next.hash);introReady.then(()=>accountDialog(create));}}).catch(()=>{});

function recordCompletedGame(){const result=matchResult(g,seat);if(!result)return;const id=online?'room:'+online.code+':'+g.version:'solo:'+g.localMatchId;const record=addResult(load('khasino-record'),{...result,id,kind:online?'friends':'computer',at:Date.now()});save('khasino-record',record);renderCompetition();}
function competitionSummary(){const r=matchResult(g,seat);if(!r)return '';const kind=online?'friends':'computer',record=load('khasino-record'),s=record?.groups?.[kind+':'+r.mode];return `<div class="result-progress"><strong>${r.outcome==='win'?'Victory':r.outcome==='draw'?'Draw':'Next hand, new chance'}</strong><span>${s?.wins||0} wins · ${s?.losses||0} losses · ${s?.draws||0} draws</span>${s?.streak>1?'<span>'+s.streak+' wins in a row</span>':''}<small>${online?'Friends games':'Computer games'} · ${esc(r.mode)} · personal device record</small></div>`;}
function renderCompetition(){const record=load('khasino-record'),solo=summarize(record,'computer'),friends=summarize(record,'friends');const games=solo.wins+solo.losses+solo.draws+friends.wins+friends.losses+friends.draws;const wins=solo.wins+friends.wins,best=Math.max(solo.bestStreak,friends.bestStreak);$('competitionPanel').innerHTML=`<div class="competition-heading"><h2>Your games</h2><button id="openCompete" class="home-signup">Compete</button><small>Personal record · this device</small></div><div class="competition-records">${[['Computer',solo],['Friends',friends]].map(([label,s])=>`<div><strong>${label}</strong><span>${s.wins} <small>W</small> &nbsp; ${s.losses} <small>L</small> &nbsp; ${s.draws} <small>D</small></span><small>Best winning streak: ${s.bestStreak}</small></div>`).join('')}<div><strong>Next milestone</strong><span>${!games?'Finish your first game':wins<1?'Get your first win':wins<5?wins+' / 5 wins':best<3?'Win 3 in a row':'Reach '+(Math.floor(wins/10)*10+10)+' wins'}</span><small>${wins>=5?'Five wins earned':wins>=1?'First win earned':'Build your record one hand at a time'}</small></div></div>${record?.recent?.length?'<div class="recent-results"><span>Recent form</span>'+record.recent.slice(0,8).reverse().map(m=>'<span class="form-result '+m.outcome+'" title="'+esc(m.kind+' · '+m.mode+' · '+m.points+' points')+'">'+({win:'W',loss:'L',draw:'D'}[m.outcome])+'</span>').join('')+'</div>':''}`;$('openCompete').onclick=()=>competeDialog();}
renderCompetition();

let queueTimer=null,queueBusy=false,queueWaiting=false;
$('modal').addEventListener('close',()=>{clearInterval(queueTimer);if(queueWaiting){queueWaiting=false;api('/api/competition/queue',{action:'cancel'}).catch(()=>{});}});
const tier=r=>r<1000?'Rookie':r<1200?'Bronze':r<1400?'Silver':r<1600?'Gold':r<1800?'Diamond':'Master';
const modeLabel=m=>m==='teams'?'Partnerships':m+' players';
async function competeDialog(){
 clearInterval(queueTimer);
 try{const data=await api('/api/competition/me');showModal(`<p class="modal-eyebrow">COMPETE</p><h3 class="modal-title">Competitive tables.</h3><p class="modal-copy">Server-verified online results. Each mode has its own rating.</p><div class="rating-cards">${['2','3','4','teams'].map(m=>{const s=data.modes[m];return `<div><small>${modeLabel(m)}</small><strong>${s?.rating??1000}</strong><span>${s?tier(s.rating):'Unrated · starts at 1000'}</span><small>${s?.wins||0} W · ${s?.losses||0} L · ${s?.draws||0} D</small></div>`;}).join('')}</div><div class="compete-actions"><button id="rankedPlay" class="primary-button">Find rated opponent</button><button id="rankedTable" class="outline-button">Rated table with friends</button><button id="rankBoard" class="outline-button">Leaderboards</button><button id="weeklyBoard" class="outline-button">Weekly league</button><button id="tourneys" class="outline-button">Tournaments</button></div><p class="rule-note">Weekly points: win 10 · draw 5 · loss 2. Weeks run Monday–Sunday UTC. Computer games never affect your rating.</p>${data.history.length?'<h4>Recent rated games</h4><div class="rated-history">'+data.history.slice(0,8).map(r=>'<div><span>'+esc(modeLabel(r.mode))+' · '+esc(r.outcome)+'</span><strong>'+r.rating+' ('+(r.delta>=0?'+':'')+r.delta+')</strong></div>').join('')+'</div>':'<p class="modal-copy">Your first rated result will appear here.</p>'}`);
 $('rankedPlay').onclick=()=>queueDialog();$('rankedTable').onclick=()=>{friendsDialog();$('ratedRoom').checked=true;};$('rankBoard').onclick=()=>leaderboardDialog(false);$('weeklyBoard').onclick=()=>leaderboardDialog(true);$('tourneys').onclick=()=>tournamentMenu();
 }catch(e){toast(e.message);accountDialog(true);}
}
async function queueDialog(){
 showModal(`<p class="modal-eyebrow">RATED · HEAD TO HEAD</p><h3 class="modal-title">Find your next opponent.</h3><p id="queueStatus" class="modal-copy">Joining the queue…</p><button id="cancelQueue" class="outline-button">Cancel</button><p class="rule-note">We start with players near your rating, then widen the range as you wait. Someone else needs to join to start a match.</p>`);
 $('cancelQueue').onclick=()=>$('modal').close();queueWaiting=true;
 const tick=async(action='status')=>{if(queueBusy)return;queueBusy=true;try{const r=await api('/api/competition/queue',{action});if(!queueWaiting)return;if(r.match){queueWaiting=false;clearInterval(queueTimer);enterRoom(r.match);}else if($('queueStatus'))$('queueStatus').textContent='Waiting for an opponent · rating '+r.rating;}catch(e){if($('queueStatus'))$('queueStatus').textContent=e.message;}finally{queueBusy=false;}};
 await tick('new');if(queueWaiting)queueTimer=setInterval(()=>tick(),2500);
}
async function leaderboardDialog(weekly,mode='2'){
 try{const d=await api('/api/competition/leaderboard?mode='+mode+'&weekly='+(weekly?'1':'0'));showModal(`<p class="modal-eyebrow">${weekly?'THIS WEEK · '+d.week:'RATED PLAY'}</p><h3 class="modal-title">${weekly?'Weekly league.':'Leaderboard.'}</h3><label class="field">Game mode<select id="boardMode">${['2','3','4','teams'].map(m=>'<option value="'+m+'" '+(mode===m?'selected':'')+'>'+modeLabel(m)+'</option>').join('')}</select></label>${d.rows.length?'<table class="score-grid"><thead><tr><th>#</th><th>Player</th><th>'+(weekly?'Points':'Rating')+'</th></tr></thead><tbody>'+d.rows.map((r,i)=>'<tr><td>'+(i+1)+'</td><td>'+esc(r.name)+'<small class="rank-tier">'+r.tier+'</small></td><td>'+(weekly?r.weeklyPoints:r.rating)+'</td></tr>').join('')+'</tbody></table>':'<p class="modal-copy">No completed rated games yet. Play a rated match to start the standings.</p>'}<button id="boardBack" class="outline-button">Back to competition</button>`);$('boardMode').onchange=()=>leaderboardDialog(weekly,$('boardMode').value);$('boardBack').onclick=()=>competeDialog();}catch(e){toast(e.message);}
}
function tournamentMenu(){showModal(`<p class="modal-eyebrow">TOURNAMENTS</p><h3 class="modal-title">Four players. One title.</h3><p class="modal-copy">Round-robin: everyone plays everyone. Six head-to-head matches. Win = 3 points, draw = 1. Highest points wins; wins break ties, then the title is shared.</p><label class="field">Tournament name<input id="tournamentName" maxlength="20" placeholder="Friday table"></label><button id="createTournament" class="primary-button">Create tournament</button><label class="field tournament-join">Tournament code<input id="tournamentCode" maxlength="6" placeholder="Six-letter code" value="${esc(load('khasino-tournament',''))}"></label><button id="joinTournament" class="outline-button">Join or return</button>`);
 $('createTournament').onclick=async()=>{try{const t=await api('/api/competition/tournaments',{name:$('tournamentName').value});save('khasino-tournament',t.code);tournamentDialog(t.code);}catch(e){toast(e.message);}};
 $('joinTournament').onclick=async()=>{const code=$('tournamentCode').value.trim().toUpperCase();try{try{await api('/api/competition/tournaments/'+code,{action:'view'});}catch{await api('/api/competition/tournaments/'+code,{action:'join'});}save('khasino-tournament',code);tournamentDialog(code);}catch(e){toast(e.message);}};
}
async function tournamentDialog(code){try{const t=await api('/api/competition/tournaments/'+code,{action:'view'});showModal(`<p class="modal-eyebrow">TOURNAMENT · ${t.code}</p><h3 class="modal-title">${esc(t.name)}</h3><p class="modal-copy">${t.status==='lobby'?t.players.length+' / 4 players joined. Share this code with your opponents.':t.status==='ended'?'Champion'+(t.winners.length>1?'s':'')+': '+t.winners.map(esc).join(' & '):'Round-robin · rated head-to-head games'}</p><table class="score-grid"><thead><tr><th>Player</th><th>Played</th><th>Points</th></tr></thead><tbody>${t.standings.map(s=>'<tr><td>'+esc(s.name)+'</td><td>'+s.played+'</td><td>'+s.points+'</td></tr>').join('')}</tbody></table>${t.matches.length?'<div class="tournament-matches">'+t.matches.map(m=>'<div><small>Round '+m.round+'</small><span>'+esc(t.players[m.pair[0]])+' vs '+esc(t.players[m.pair[1]])+'</span><strong>'+(m.scores?m.scores.join(' – '):m.status==='playing'?'Playing':'Waiting')+'</strong></div>').join('')+'</div>':''}<div class="modal-actions">${t.status==='lobby'&&t.host?'<button id="startTournament" class="primary-button" '+(t.players.length<4?'disabled':'')+'>Start tournament</button>':''}${t.status==='playing'&&t.matches.some(m=>m.pair.includes(t.me)&&m.status!=='ended')?'<button id="playTournament" class="primary-button">Play next match</button>':''}<button id="refreshTournament" class="outline-button">Refresh</button><button id="tournamentBack" class="outline-button">Back</button></div>`);
 if($('startTournament'))$('startTournament').onclick=async()=>{try{await api('/api/competition/tournaments/'+code,{action:'start'});tournamentDialog(code);}catch(e){toast(e.message);}};
 if($('playTournament'))$('playTournament').onclick=async()=>{try{const r=await api('/api/competition/tournaments/'+code,{action:'play'});enterRoom(r.match);}catch(e){toast(e.message);}};
 $('refreshTournament').onclick=()=>tournamentDialog(code);$('tournamentBack').onclick=()=>competeDialog();
 }catch(e){toast(e.message);}}

const competeMenuButton=document.createElement('button');competeMenuButton.className='quiet-button';competeMenuButton.textContent='Compete';menu.append(competeMenuButton);competeMenuButton.onclick=()=>{ $('tableMenu').open=false;competeDialog();};

function cancelMovePlayback(){playbackEpoch++;for(const el of document.querySelectorAll('.move-flight')){for(const a of el.getAnimations())a.cancel();el.remove();}}
async function animateMoves(moves,old,next,previous,origins,epoch){
 if(epoch!==playbackEpoch||atHome||reduced)return;
 const skip=new Set(moves.flatMap(m=>[m.card.id,...m.captured.map(c=>c.id)]));animateOther(old,next,previous,skip);
 for(const m of moves){if(epoch!==playbackEpoch||atHome||reduced)break;const label=m.actor===seat?'You':next.names[m.actor];$('turnBadge').textContent=label+(m.type==='capture'?' chows with ':' plays ')+E.label(m.card);
  const source=old.find(c=>c.id===m.card.id)?.rect||origins.find(o=>o.player===m.actor)?.rect||$('hand').getBoundingClientRect();
  const floor=$('floor').getBoundingClientRect(),target=m.target?document.querySelector(`[data-table="${m.target}"]`)?.getBoundingClientRect():null;
  const width=target?.width||(innerWidth<=760?56:90),height=width*1.42;
  const captured=m.captured.map(c=>({card:c,snapshot:old.find(s=>s.id===c.id)}));
  const rects=captured.filter(c=>c.snapshot).map(c=>c.snapshot.rect),cx=rects.length?rects.reduce((n,r)=>n+r.x+r.width/2,0)/rects.length:floor.x+floor.width/2,cy=rects.length?rects.reduce((n,r)=>n+r.y+r.height/2,0)/rects.length:floor.y+floor.height/2;
  const landing={x:target?.x??Math.max(floor.x,Math.min(floor.right-width,cx-width/2)),y:target?.y??Math.max(floor.y,Math.min(floor.bottom-height,cy-height/2)),width,height};
  const ghosts=[],hidden=[];const mask=el=>{if(el&&!hidden.some(h=>h.el===el)){hidden.push({el,visibility:el.style.visibility});el.style.visibility='hidden';}};
  const make=(c,r)=>{const temp=document.createElement('div');temp.innerHTML=card(c,{extra:'flying move-flight',attrs:'tabindex="-1" aria-hidden="true"'});const el=temp.firstElementChild;Object.assign(el.style,{left:r.x+'px',top:r.y+'px',width:r.width+'px',height:r.height+'px'});$('flightLayer').append(el);ghosts.push(el);return el;};
  const run=async(el,frames,options)=>{try{await el.animate(frames,{fill:'forwards',easing:'cubic-bezier(.2,.8,.2,1)',...options}).finished;}catch{}};
  try{
   if(m.type==='capture')for(const c of captured){if(c.snapshot)make(c.card,c.snapshot.rect);}
   const final=m.type==='capture'?document.querySelector(`[data-pile-target="${m.actor}"] .card`):m.target?document.querySelector(`[data-table="${m.target}"]`):null;mask(final);
   const fly=make(m.card,landing),dx=source.x+source.width/2-landing.x-width/2,dy=source.y+source.height/2-landing.y-height/2,scale=Math.min(1,Math.max(.3,source.width/width));
   await run(fly,[{transform:`translate(${dx}px,${dy}px) scale(${scale}) rotate(-7deg)`,opacity:1},{transform:'translate(0,0) scale(1) rotate(0deg)',opacity:1}],{duration:550});
   if(epoch!==playbackEpoch)break;
   await run(fly,[{transform:'scale(1)'},{transform:'scale(1)'}],{duration:m.type==='capture'?330:180});
   if(m.type==='capture'){const dest=document.querySelector(`[data-pile-target="${m.actor}"]`)?.getBoundingClientRect();if(dest){await Promise.all(ghosts.map((el,i)=>{const r=el.getBoundingClientRect();return run(el,[{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dest.x-r.x}px,${dest.y-r.y}px) scale(${Math.max(.3,dest.width/r.width)}) rotate(4deg)`,opacity:.15}],{duration:450,delay:i*20});}));}}
  }finally{for(const el of ghosts)el.remove();for(const h of hidden)h.el.style.visibility=h.visibility;}
 }
}


function receiveClock(r){turnClock=r.clock;timeoutSeats=r.timeoutSeats||[];serverOffset=(r.serverNow||Date.now())-Date.now();}
const timerBadge=document.createElement('button');timerBadge.className='turn-clock';timerBadge.hidden=true;$('table').append(timerBadge);
timerBadge.onclick=async()=>{if(!online||!timeoutSeats[seat]?.bot)return;try{const r=await api('/api/rooms/'+online.code+'/resume',{token:online.token});receiveClock(r);setGame(r.game);}catch(e){toast(e.message);}};
setInterval(()=>{
 const active=online&&g?.status==='playing'&&!atHome;timerBadge.hidden=!active;if(!active)return;
 const bot=timeoutSeats[seat]?.bot,remaining=Math.max(0,Math.ceil(((g.leaveOffer?.endsAt||turnClock?.endsAt||Date.now())-Date.now()-serverOffset)/1000));
 timerBadge.textContent=bot?'Computer playing · Take back seat':(g.leaveOffer?'Leave it?':g.names[g.turn])+' · '+remaining+'s';timerBadge.classList.toggle('urgent',remaining<=15);timerBadge.classList.toggle('take-seat',!!bot);
 const key=g.version+':'+remaining;if(remaining>0&&remaining<=5&&key!==lastClockTick&&!g.leaveOffer){lastClockTick=key;foley('tap');}
},250);
